package io.nodle.dtn.bpv7

import io.nodle.dtn.bpv7.extensions.getHopCountBlockData
import io.nodle.dtn.utils.hexToBa
import org.junit.Assert.*
import org.junit.Test
import java.io.ByteArrayInputStream
import java.net.URI

class WireFormatTest {
    @Test
    fun crcUsesReceivedEncodingIncludingBreak() {
        // CRC16 values calculated independently over the encoded block, with only CRC value bytes zeroed.
        val block = cborUnmarshalCanonicalBlock("9f010100014301020342be5cff".hexToBa())
        assertEquals(BlobBlockData(byteArrayOf(1, 2, 3)), block.data)
        cborUnmarshalCanonicalBlock(block.cborMarshal())
    }

    @Test
    fun primaryEncodingIsPreservedWhileFieldsAreUnchanged() {
        val encoded = "9f0700018201008201008201008200011903e84207ddff".hexToBa()
        val primary = cborUnmarshalPrimaryBlock(encoded)
        assertArrayEquals(encoded, primary.cborMarshal())
        primary.lifetime++
        assertEquals(1001L, cborUnmarshalPrimaryBlock(primary.cborMarshal()).lifetime)
    }

    @Test
    fun knownExtensionDataIsNotReencodedUntilModified() {
        val encoded = "860a020001449f0a00ff42fc32".hexToBa()
        val block = cborUnmarshalCanonicalBlock(encoded)
        assertArrayEquals(encoded, block.cborMarshal())
        val bundle = Bundle(PrimaryBlock(), mutableListOf(block))
        bundle.getHopCountBlockData()!!.count++
        val modified = cborUnmarshalCanonicalBlock(block.cborMarshal())
        assertFalse(encoded.contentEquals(modified.cborMarshal()))
    }

    @Test
    fun streamingHandlesReadAheadAndConcatenatedBundles() {
        val bundle = PrimaryBlock(source = URI.create("dtn://source/"))
            .makeBundle()
            .addBlock(CanonicalBlock(blockType = 200, data = BlobBlockData(ByteArray(40000) { it.toByte() })))
            .addBlock(payloadBlock(byteArrayOf(1, 2, 3)).crcType(CRCType.CRC32))
        val encoded = bundle.cborMarshal()
        createBpv7Parser(ByteArrayInputStream(encoded + encoded)).use { parser ->
            assertEquals(bundle, parser.readBundleOrNull())
            assertEquals(bundle, parser.readBundleOrNull())
            assertNull(parser.readBundleOrNull())
        }
    }

    @Test
    fun malformedCrcAndChunkedBlockDataAreRejected() {
        for (hex in listOf(
            "8618c80200014301020342da1f", // corrupted CRC
            "8618c8020001430102034100", // CRC16 with one value byte
            "8518c80200005f4101ff" // indefinite-length block-type-specific byte string
        )) {
            assertThrows(Exception::class.java) { cborUnmarshalCanonicalBlock(hex.hexToBa()) }
        }
    }

    @Test
    fun localBlockLimitDoesNotLimitJacksonReadAheadOfLaterBlocks() {
        val bundle = PrimaryBlock(source = URI.create("dtn://source/")).makeBundle()
            .addBlock(payloadBlock(byteArrayOf(1)))
        val encoded = bundle.cborMarshal()
        createBpv7Parser(ByteArrayInputStream(encoded + encoded), 512).use { parser ->
            assertNotNull(parser.readBundleOrNull())
            assertNotNull(parser.readBundleOrNull())
        }
        createBpv7Parser(ByteArrayInputStream(
            bundle.apply { getPayloadBlockData().buffer = ByteArray(600) }.cborMarshal()
        ), 512).use { parser ->
            assertThrows(CborParsingException::class.java) { parser.readBundle() }
        }
    }

    @Test
    fun rustBp7_0_10_7FixtureIsPreservedAndTruncationIsRejected() {
        // Generated by the dtn7-rs locked codec bp7 0.10.7, with CRC32C on every block.
        val encoded = (
            "9f8907000282016e2f2f64657374696e6174696f6e2f8201692f2f736f757263652f" +
                "8201692f2f7265706f72742f8200182a1a0036ee80443c8c7d4d" +
                "860702000242186444e2db29a68618c804000243ff000144fa4ff973" +
                "8601010002412a44708baab2ff"
            ).hexToBa()
        val bundle = cborUnmarshalBundle(encoded)
        bundle.checkValid()
        assertEquals(BlobBlockData(byteArrayOf(0xff.toByte(), 0, 1)), bundle.getBlockNumber(4)!!.data)
        assertArrayEquals(encoded, bundle.cborMarshal())
        for (length in encoded.indices) {
            assertThrows(Exception::class.java) { cborUnmarshalBundle(encoded.copyOf(length)) }
        }
    }
}
